using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.RegularCHS;

internal sealed class NewtonDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Complete homogeneous symmetric adjacency coefficients.",
        H("Newton"), Blocks(
            Describe.Lean(DescribeId.Create("regular-chs-newton-0"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.bseq_nonneg"),
                H("Nonnegative comparison coefficients"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For all natural n, r and m, bseq n r m is nonnegative. The recursion has nonnegative factors and a positive denominator."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-1"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.bseq_mono"),
                H("Monotonicity in the degree parameter"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For natural n and r with r at least four, and every natural m, bseq n 4 m is at most bseq n r m."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-2"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.trace_pow_eq_closedWalks"),
                H("Traces and natural walk counts"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every simple graph G on Fin n and every natural k, the trace of the kth power of the real adjacency matrix equals the real coercion of closedWalks G k. The natural-to-real ring homomorphism commutes with matrix powers."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-3"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.sum_eigenvalues_pow_eq_closedWalks"),
                H("Spectral moments count walks"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every simple graph G on Fin n and every natural k, the sum of the kth powers of its real adjacency eigenvalues equals the real coercion of closedWalks G k. Unitary diagonalization preserves the trace."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-4"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.hsymm_newton"),
                H("The complete homogeneous Newton recurrence"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every finite decidable type of indices, every real family a and every natural d, d plus one times the complete homogeneous symmetric value at degree d plus one equals the sum over k from zero through d of the power sum of degree k plus one times the complete homogeneous value of degree d minus k. The reciprocal linear-factor product identifies the generating series, and formal differentiation gives the recurrence."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-5"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.chs_newton"),
                H("The graph Newton recurrence"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every simple graph G on Fin n and every natural d, d plus one times chs G at d plus one equals the sum over k from zero through d of closedWalks G at k plus one times chs G at d minus k. Walk counts are coerced to the real numbers."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-6"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.chs_nonneg"),
                H("Nonnegative adjacency coefficients"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every simple graph G on Fin n and every natural d, chs G d is nonnegative. Strong induction uses nonnegative closed walk counts in the Newton recurrence. Odd degrees are included."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-7"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.chs_le_of_closedWalks_le"),
                H("Closed walk domination implies coefficient domination"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("Let F and G be simple graphs on the same Fin n. If closedWalks F k is at most closedWalks G k for every positive natural k, then chs F d is at most chs G d for every natural d. The induction combines both moment domination and nonnegativity of earlier coefficients."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-8"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.chs_le_top"),
                H("The complete graph upper bound"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every simple graph G on Fin n and every natural d, chs G d is at most the coefficient of degree d of the complete graph on Fin n. Entrywise adjacency domination is preserved by powers of nonnegative matrices."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-9"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.chs_two_mul_pos"),
                H("Nonnegativity in even degree"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every simple graph G on Fin n and every natural m, chs G at degree 2m is nonnegative. No strict positivity or edge assumption is asserted here."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-10"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.bseq_convolution"),
                H("The even Newton convolution for the comparison sequence"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For all natural n, r and m, 2m times bseq n r m equals n times the sum over j less than m of r to the power j plus one times bseq n r at m minus one minus j. All coefficient arithmetic is real. The defining first-order recurrence telescopes to this convolution."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("regular-chs-newton-11"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/RegularCHS/Newton.chs_ge_bseq"),
                H("Even moment lower bounds imply coefficient lower bounds"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/GraphInvariants/chavez2023extremalpolynomialnorms")),
                Blocks(Paragraph(Text("For every graph G on Fin n, natural parameter r and natural m, if n times r to the power j is at most closedWalks G at length 2j for every positive j, then bseq n r m is at most chs G at degree 2m. Select the even moments from the Newton recurrence, discard nonnegative remaining terms, and apply induction to the earlier even coefficients. No additional minimum degree premise is needed."))), DescribeRole.Theorem))));
}
